actions.script:
const given = name => (typeof ec.context[name] === 'undefined' || ec.context[name] === '' ? null : ec.context[name])
const services = {create: 'create#RecordGuestShare', send: 'send#RecordGuestLink'}
let out = {}
let error = ''
ec.message.pushErrors()
try {
    const thru = Number(given('thruDate'))
    out = ec.service.sync().name('mantle.other.LocationShareServices.' + services[given('op')])
        .parameters({recordType: given('recordType'), recordId: given('recordId'), thruDate: thru ? new Date(thru) : null,
            purposeText: given('purposeText'), shareId: given('shareId'), linkSecret: given('linkSecret')})
        .disableAuthz().requireNewTransaction(true).call() || {}
    if (ec.message.hasError()) error = ec.message.getErrorsString()
} catch (e) {
    error = String(e.message || e)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (out.thruDate) out.thruDate = ec.user.timestampMillis(out.thruDate)
ec.web.sendJsonResponse({out, error})
